example:
blueprint: open-orders
permissions: [records:read]

steps:
  open:
    do: rows.read
    with: { collection: orders, saying: { status: open } }

  said:
    when: ${ steps.open.out.those[0] != null }
    do: log
    with: { message: "The first open order is ${ steps.open.out.those[0] }." }
